import functools

# Begin code
@functools.lru_cache(maxsize=None)  # Use lru_cache from functools module to enable memoization
def fib_memoized(n):
    """
    Recursive Fibonacci function with memoization.
    """
    if n < 0:
        raise ValueError("Input must be non-negative.")
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fib_memoized(n-1) + fib_memoized(n-2)

